const DICTS: Record<Lang, MiniDict> = { es, pt, en };

export function miniT(lang: Lang): MiniDict {
  return DICTS[lang] ?? es;
}

/** Fills `{key}` placeholders. */
export function fill(s: string, vars: Record<string, string | number>): string {
  return s.replace(/\{(\w+)\}/g, (_, k: string) => String(vars[k] ?? ""));
}

/** Picks a language from a ?lang= value, then the phone's language, defaulting to es. */
export function pickLang(param: string | null | undefined, navigatorLang?: string | null): Lang {
  if (param === "es" || param === "pt" || param === "en") return param;
  const n = (navigatorLang ?? "").toLowerCase();
  if (n.startsWith("pt")) return "pt";
  if (n.startsWith("en")) return "en";
  return "es";
}

/** The display currency per language (design: es → pesos, pt → reais, en → dollars). */
export const DISPLAY_CUR: Record<Lang, Cur> = { es: "ARS", pt: "BRL", en: "USD" };
